class MuonWarm(torch.optim.Optimizer):
    """
    Muon optimizer with auxiliary Adam for non-matrix params.
    
    Supports double momentum mode (inspired by AdEMAMix) for muon params:
    - muon_double_momentum_mode=None: Standard single momentum
    - muon_double_momentum_mode="pre_ns": Blend fast/slow momentum before Newton-Schulz
    - muon_double_momentum_mode="post_ns": Apply NS to both, blend after
    
    Args:
        params: Model parameters or param_groups (use get_muon_param_groups helper)
        adam_lr: Learning rate for Adam params (default: 3e-4)
        adam_betas: Beta coefficients for Adam (default: (0.9, 0.95))
        adam_eps: Epsilon for Adam (default: 1e-10)
        adam_weight_decay: Weight decay for Adam params (default: 0)
        muon_lr: Learning rate for Muon params (default: 0.02)
        muon_momentum: Fast momentum beta for Muon (default: 0.95)
        muon_weight_decay: Weight decay for Muon params (default: 0)
        muon_ns_steps: Newton-Schulz iteration steps (default: 5)
        muon_nesterov: Use Nesterov momentum (default: True)
    """
    def __init__(
        self,
        params,
        # Adam params
        adam_lr=3e-4,
        adam_betas=(0.9, 0.999),
        adam_eps=1e-10,
        adam_weight_decay=0,
        # Muon params
        muon_lr=0.02,
        muon_momentum=0.95,
        muon_weight_decay=0,
        muon_ns_steps=5,
        muon_polar_method="muon",
        muon_nesterov=True,
        muon_warm_anchor_every=8,
        muon_warm_lr=1.0,
        muon_warm_jacobi_eps=1e-3,
        muon_warm_retract_method="higham_cubic",
        muon_warm_retract_steps=1,
        muon_warm_retract_every=1,
        muon_warm_anchor_retract_method="higham_cubic",
        muon_warm_anchor_retract_steps=2,
        muon_warm_full_ns_steps=2500,
        muon_warm_track_subspace=True,
        muon_warm_max_tracking_error=0.0,
        muon_warm_min_alignment=0.0,
        muon_warm_min_stretch=0.0,
        muon_warm_max_age=0,
        muon_warm_max_rejection_streak=0,
        muon_warm_check_every=1,
        muon_warm_stagger_anchors=False,
        muon_warm_jacobi_damping="floor",
        muon_warm_max_tangent_rms=0.0,
        muon_warm_alignment_tolerance=-1.0,
        muon_warm_record_stats=False,
        muon_warm_tangent_ema_beta=0.95,
        muon_warm_max_tangent_ratio=0.0,
        muon_warm_angular_scale=1.0,
        muon_warm_normal_scale=1.0,
        muon_warm_normal_inv_cap=0.0,
        muon_warm_normal_inv_ema_ratio=0.0,
        muon_warm_normal_inv_ema_beta=0.95,
        muon_warm_max_angular_rms=0.0,
        muon_warm_max_skew_ratio=0.0,
        muon_warm_async_checks=False,
        muon_warm_update_stats_every=0,
        muon_warm_reference_lr_ratio=1.0,
        muon_warm_normalize_output=False,
        muon_warm_output_scale=1.0,
        muon_warm_output_scale_start=None,
        muon_warm_output_scale_decay=1.0,
        muon_warm_legacy_retraction_output=False,
        muon_warm_spectral_cap_mode="gershgorin",
        muon_warm_power_steps=2,
        muon_warm_power_safety_factor=1.25,
    ):
        # Store muon-specific settings
        self.muon_ns_steps = muon_ns_steps
        self.muon_polar_method = muon_polar_method
        self.muon_nesterov = muon_nesterov
        self.muon_warm_anchor_every = muon_warm_anchor_every
        self.muon_warm_lr = muon_warm_lr
        self.muon_warm_jacobi_eps = muon_warm_jacobi_eps
        self.muon_warm_retract_method = muon_warm_retract_method
        self.muon_warm_retract_steps = muon_warm_retract_steps
        self.muon_warm_retract_every = int(muon_warm_retract_every)
        self.muon_warm_anchor_retract_method = (
            muon_warm_anchor_retract_method
        )
        self.muon_warm_anchor_retract_steps = int(
            muon_warm_anchor_retract_steps
        )
        self.muon_warm_full_ns_steps = max(0, int(muon_warm_full_ns_steps))
        self.muon_warm_track_subspace = bool(muon_warm_track_subspace)
        self.muon_warm_max_tracking_error = float(muon_warm_max_tracking_error)
        self.muon_warm_min_alignment = float(muon_warm_min_alignment)
        self.muon_warm_min_stretch = float(muon_warm_min_stretch)
        self.muon_warm_max_age = int(muon_warm_max_age)
        self.muon_warm_max_rejection_streak = int(
            muon_warm_max_rejection_streak
        )
        self.muon_warm_check_every = max(1, int(muon_warm_check_every))
        self.muon_warm_stagger_anchors = bool(muon_warm_stagger_anchors)
        self.muon_warm_jacobi_damping = muon_warm_jacobi_damping
        self.muon_warm_max_tangent_rms = float(muon_warm_max_tangent_rms)
        self.muon_warm_alignment_tolerance = float(
            muon_warm_alignment_tolerance
        )
        self.muon_warm_record_stats = bool(muon_warm_record_stats)
        self.muon_warm_tangent_ema_beta = float(muon_warm_tangent_ema_beta)
        self.muon_warm_max_tangent_ratio = float(muon_warm_max_tangent_ratio)
        self.muon_warm_angular_scale = float(muon_warm_angular_scale)
        self.muon_warm_normal_scale = float(muon_warm_normal_scale)
        self.muon_warm_normal_inv_cap = float(muon_warm_normal_inv_cap)
        self.muon_warm_normal_inv_ema_ratio = float(
            muon_warm_normal_inv_ema_ratio
        )
        self.muon_warm_normal_inv_ema_beta = float(
            muon_warm_normal_inv_ema_beta
        )
        self.muon_warm_max_angular_rms = float(muon_warm_max_angular_rms)
        self.muon_warm_max_skew_ratio = float(muon_warm_max_skew_ratio)
        self.muon_warm_async_checks = bool(muon_warm_async_checks)
        self.muon_warm_update_stats_every = int(muon_warm_update_stats_every)
        self.muon_warm_reference_lr_ratio = float(
            muon_warm_reference_lr_ratio
        )
        self.muon_warm_normalize_output = bool(muon_warm_normalize_output)
        self.muon_warm_output_scale = float(muon_warm_output_scale)
        self.muon_warm_output_scale_start = (
            None
            if muon_warm_output_scale_start is None
            else float(muon_warm_output_scale_start)
        )
        self.muon_warm_output_scale_decay = float(
            muon_warm_output_scale_decay
        )
        self.muon_warm_legacy_retraction_output = bool(
            muon_warm_legacy_retraction_output
        )
        self.muon_warm_spectral_cap_mode = muon_warm_spectral_cap_mode
        self.muon_warm_power_steps = int(muon_warm_power_steps)
        self.muon_warm_power_safety_factor = float(
            muon_warm_power_safety_factor
        )
        self._next_muon_anchor_offset = 0
        self._muon_warm_pending_drift_checks = {}
        if self.muon_warm_lr < 0.0:
            raise ValueError("muon_warm_lr must be non-negative")
        if self.muon_warm_max_tracking_error < 0.0:
            raise ValueError("muon_warm_max_tracking_error must be non-negative")
        if self.muon_warm_min_alignment < 0.0:
            raise ValueError("muon_warm_min_alignment must be non-negative")
        if self.muon_warm_min_stretch < 0.0:
            raise ValueError("muon_warm_min_stretch must be non-negative")
        if self.muon_warm_max_age < 0:
            raise ValueError("muon_warm_max_age must be non-negative")
        if self.muon_warm_max_rejection_streak < 0:
            raise ValueError(
                "muon_warm_max_rejection_streak must be non-negative"
            )
        if (
            self.muon_warm_max_rejection_streak > 0
            and self.muon_warm_alignment_tolerance < 0.0
        ):
            raise ValueError(
                "muon_warm_max_rejection_streak requires a non-negative "
                "muon_warm_alignment_tolerance"
            )
        if self.muon_warm_jacobi_damping not in ("floor", "tikhonov"):
            raise ValueError(
                "muon_warm_jacobi_damping must be 'floor' or 'tikhonov'"
            )
        if self.muon_polar_method not in ("muon", "polar_express"):
            raise ValueError(
                "muon_polar_method must be 'muon' or 'polar_express'"
            )
        if self.muon_warm_max_tangent_rms < 0.0:
            raise ValueError("muon_warm_max_tangent_rms must be non-negative")
        if not 0.0 <= self.muon_warm_tangent_ema_beta < 1.0:
            raise ValueError(
                "muon_warm_tangent_ema_beta must be in [0, 1)"
            )
        if self.muon_warm_max_tangent_ratio < 0.0:
            raise ValueError(
                "muon_warm_max_tangent_ratio must be non-negative"
            )
        if self.muon_warm_retract_method not in ("higham_cubic", "quadratic"):
            raise ValueError(
                "muon_warm_retract_method must be 'higham_cubic' or 'quadratic', "
                f"got {self.muon_warm_retract_method!r}"
            )
        if self.muon_warm_anchor_retract_method not in (
            "higham_cubic",
            "quadratic",
        ):
            raise ValueError(
                "muon_warm_anchor_retract_method must be 'higham_cubic' "
                f"or 'quadratic', got {self.muon_warm_anchor_retract_method!r}"
            )
        if self.muon_warm_anchor_retract_steps < 0:
            raise ValueError(
                "muon_warm_anchor_retract_steps must be non-negative"
            )
        if int(self.muon_warm_retract_steps) < 0:
            raise ValueError("muon_warm_retract_steps must be non-negative")
        if self.muon_warm_retract_every < 1:
            raise ValueError("muon_warm_retract_every must be >= 1")
        if self.muon_warm_angular_scale < 0.0:
            raise ValueError("muon_warm_angular_scale must be non-negative")
        if self.muon_warm_normal_scale < 0.0:
            raise ValueError("muon_warm_normal_scale must be non-negative")
        if self.muon_warm_normal_inv_cap < 0.0:
            raise ValueError("muon_warm_normal_inv_cap must be non-negative")
        if self.muon_warm_normal_inv_ema_ratio < 0.0:
            raise ValueError(
                "muon_warm_normal_inv_ema_ratio must be non-negative"
            )
        if not 0.0 <= self.muon_warm_normal_inv_ema_beta < 1.0:
            raise ValueError(
                "muon_warm_normal_inv_ema_beta must be in [0, 1)"
            )
        if (
            self.muon_warm_normal_inv_ema_ratio > 0.0
            and self.muon_warm_normal_inv_cap <= 0.0
        ):
            raise ValueError(
                "muon_warm_normal_inv_ema_ratio requires a positive "
                "muon_warm_normal_inv_cap safety ceiling"
            )
        if self.muon_warm_max_angular_rms < 0.0:
            raise ValueError("muon_warm_max_angular_rms must be non-negative")
        if self.muon_warm_max_skew_ratio < 0.0:
            raise ValueError("muon_warm_max_skew_ratio must be non-negative")
        if (
            self.muon_warm_max_angular_rms > 0.0
            and self.muon_warm_max_skew_ratio > 0.0
        ):
            raise ValueError(
                "muon_warm_max_angular_rms and muon_warm_max_skew_ratio "
                "are mutually exclusive"
            )
        if self.muon_warm_update_stats_every < 0:
            raise ValueError("muon_warm_update_stats_every must be non-negative")
        if self.muon_warm_reference_lr_ratio < 0.0:
            raise ValueError("muon_warm_reference_lr_ratio must be non-negative")
        if self.muon_warm_output_scale < 0.0:
            raise ValueError("muon_warm_output_scale must be non-negative")
        if (
            self.muon_warm_output_scale_start is not None
            and self.muon_warm_output_scale_start < 0.0
        ):
            raise ValueError(
                "muon_warm_output_scale_start must be non-negative"
            )
        if self.muon_warm_output_scale_decay < 0.0:
            raise ValueError(
                "muon_warm_output_scale_decay must be non-negative"
            )
        if self.muon_warm_spectral_cap_mode not in (
            "gershgorin",
            "power",
            "power_step",
        ):
            raise ValueError(
                "muon_warm_spectral_cap_mode must be 'gershgorin', 'power', "
                "or 'power_step'"
            )
        if (
            self.muon_warm_legacy_retraction_output
            and self.muon_warm_spectral_cap_mode != "power_step"
        ):
            raise ValueError(
                "muon_warm_legacy_retraction_output requires the "
                "'power_step' spectral cap mode"
            )
        if self.muon_warm_power_steps < 1:
            raise ValueError("muon_warm_power_steps must be >= 1")
        if self.muon_warm_power_safety_factor < 1.0:
            raise ValueError(
                "muon_warm_power_safety_factor must be >= 1"
            )
        if (
            self.muon_warm_max_angular_rms > 0.0
            and self.muon_warm_spectral_cap_mode
            not in ("gershgorin", "power_step")
        ):
            raise ValueError(
                "muon_warm_max_angular_rms requires the 'gershgorin' or "
                "'power_step' spectral cap mode"
            )
        if (
            self.muon_warm_max_skew_ratio > 0.0
            and self.muon_warm_spectral_cap_mode != "power_step"
        ):
            raise ValueError(
                "muon_warm_max_skew_ratio requires the 'power_step' "
                "spectral cap mode"
            )
        if (
            self.muon_warm_normal_inv_ema_ratio > 0.0
            and self.muon_warm_spectral_cap_mode != "gershgorin"
        ):
            raise ValueError(
                "muon_warm_normal_inv_ema_ratio currently requires the "
                "'gershgorin' spectral cap mode"
            )
        if (
            self.muon_warm_normal_inv_ema_ratio > 0.0
            and self.muon_warm_max_angular_rms > 0.0
        ):
            raise ValueError(
                "muon_warm_normal_inv_ema_ratio cannot currently be combined "
                "with muon_warm_max_angular_rms"
            )
        
        # Convert params to param_groups if needed
        if isinstance(params, dict):
            param_groups = [params]
        elif hasattr(params, '__iter__') and not isinstance(params, torch.Tensor):
            param_groups = list(params)
            if len(param_groups) > 0 and not isinstance(param_groups[0], dict):
                # It's an iterable of tensors, not param groups
                param_groups = [{"params": param_groups}]
        else:
            param_groups = [{"params": [params]}]
        
        # Apply defaults to each group
        for group in param_groups:
            if "use_muon" not in group:
                # Default: use muon for 2D+, adam for 1D
                # This shouldn't happen if using get_muon_param_groups
                group["use_muon"] = True
            
            if group["use_muon"]:
                group.setdefault("muon_split_count", 1)
                group.setdefault("lr", muon_lr)
                group.setdefault("momentum", muon_momentum)
                group.setdefault("weight_decay", muon_weight_decay)
            else:
                group.setdefault("lr", adam_lr)
                group.setdefault("betas", adam_betas)
                group.setdefault("eps", adam_eps)
                group.setdefault("weight_decay", adam_weight_decay)
        
        super().__init__(param_groups, dict())

    def _prepare_tracking_matrix(
        self,
        work_matrix,
        q_prev,
        state,
        transposed,
    ):
        """Return the matrix whose polar factor is tracked between anchors."""
        return work_matrix

    def _compute_anchor_direction(self, work_matrix, state, transposed):
        q_next = _polar_solve_prepared(
            work_matrix,
            self.muon_ns_steps,
            self.muon_polar_method,
        )
        return _row_ns_retract(
            q_next,
            self.muon_warm_anchor_retract_steps,
            self.muon_warm_anchor_retract_method,
            False,
        )

    @staticmethod
    def _record_power_cap_state(
        state,
        power_vector,
        power_sigma,
        cap_scale,
        probe_sigma=None,
        step_scale=None,
        record_adjusted=True,
    ):
        state["muon_warm_power_vector"] = power_vector
        if record_adjusted:
            state["muon_warm_power_sigma_tensor"] = power_sigma
            state["muon_warm_spectral_cap_scale_tensor"] = cap_scale
            state["muon_warm_power_sigma_sum_tensor"] = state.get(
                "muon_warm_power_sigma_sum_tensor",
                torch.zeros_like(power_sigma),
            ) + power_sigma
            state["muon_warm_spectral_cap_scale_sum_tensor"] = state.get(
                "muon_warm_spectral_cap_scale_sum_tensor",
                torch.zeros_like(cap_scale),
            ) + cap_scale
            state["muon_warm_spectral_cap_min_scale_tensor"] = torch.minimum(
                state.get(
                    "muon_warm_spectral_cap_min_scale_tensor", cap_scale
                ),
                cap_scale,
            )
            state["muon_warm_power_cap_samples"] = int(
                state.get("muon_warm_power_cap_samples", 0)
            ) + 1
        if probe_sigma is not None and step_scale is not None:
            state["muon_warm_power_probe_sigma_tensor"] = probe_sigma
            state["muon_warm_spectral_step_scale_tensor"] = step_scale
            state["muon_warm_power_probe_sigma_sum_tensor"] = state.get(
                "muon_warm_power_probe_sigma_sum_tensor",
                torch.zeros_like(probe_sigma),
            ) + probe_sigma
            state["muon_warm_spectral_step_scale_sum_tensor"] = state.get(
                "muon_warm_spectral_step_scale_sum_tensor",
                torch.zeros_like(step_scale),
            ) + step_scale
            state["muon_warm_spectral_step_min_scale_tensor"] = torch.minimum(
                state.get(
                    "muon_warm_spectral_step_min_scale_tensor", step_scale
                ),
                step_scale,
            )
            state["muon_warm_power_step_samples"] = int(
                state.get("muon_warm_power_step_samples", 0)
            ) + 1

    def _normal_inv_dynamic_cap(self, state):
        if self.muon_warm_normal_inv_ema_ratio <= 0.0:
            return None
        ema_square = state.get("muon_warm_normal_inv_ema_sq_tensor")
        if ema_square is None:
            return None
        return float(self.muon_warm_normal_inv_ema_ratio) * ema_square.sqrt()

    def _record_normal_inv_ema_state(
        self,
        state,
        observation_rms,
        dynamic_cap,
    ):
        observation_square = observation_rms.square()
        ema_square = state.get("muon_warm_normal_inv_ema_sq_tensor")
        if ema_square is None:
            ema_square = observation_square
        else:
            ema_square = ema_square.lerp(
                observation_square,
                1.0 - self.muon_warm_normal_inv_ema_beta,
            )
        state["muon_warm_normal_inv_ema_sq_tensor"] = ema_square
        state["muon_warm_normal_inv_observation_sum_tensor"] = state.get(
            "muon_warm_normal_inv_observation_sum_tensor",
            torch.zeros_like(observation_rms),
        ) + observation_rms
        state["muon_warm_normal_inv_ema_samples"] = int(
            state.get("muon_warm_normal_inv_ema_samples", 0)
        ) + 1
        if dynamic_cap is not None:
            state["muon_warm_normal_inv_dynamic_cap_tensor"] = dynamic_cap
            state["muon_warm_normal_inv_dynamic_cap_sum_tensor"] = state.get(
                "muon_warm_normal_inv_dynamic_cap_sum_tensor",
                torch.zeros_like(dynamic_cap),
            ) + dynamic_cap
            state["muon_warm_normal_inv_dynamic_cap_min_tensor"] = torch.minimum(
                state.get(
                    "muon_warm_normal_inv_dynamic_cap_min_tensor",
                    dynamic_cap,
                ),
                dynamic_cap,
            )
            state["muon_warm_normal_inv_dynamic_cap_samples"] = int(
                state.get("muon_warm_normal_inv_dynamic_cap_samples", 0)
            ) + 1
            fixed_cap = dynamic_cap.new_tensor(self.muon_warm_normal_inv_cap)
            effective_cap = torch.minimum(fixed_cap, dynamic_cap)
            active = (dynamic_cap < fixed_cap).to(torch.float32)
            state["muon_warm_normal_inv_effective_cap_sum_tensor"] = state.get(
                "muon_warm_normal_inv_effective_cap_sum_tensor",
                torch.zeros_like(effective_cap),
            ) + effective_cap
            state["muon_warm_normal_inv_ema_active_sum_tensor"] = state.get(
                "muon_warm_normal_inv_ema_active_sum_tensor",
                torch.zeros_like(active),
            ) + active

    @staticmethod
    def _apply_drift_check_results(
        entries,
        triggers,
        flag_key,
        checks_key,
        asynchronous: bool,
    ):
        for (state, captured_anchor_serial), trigger in zip(entries, triggers):
            state[checks_key] = int(state.get(checks_key, 0)) + 1
            if int(state.get("muon_warm_anchor_serial", 0)) != int(
                captured_anchor_serial
            ):
                state["muon_warm_async_stale_checks"] = int(
                    state.get("muon_warm_async_stale_checks", 0)
                ) + 1
                continue
            state[flag_key] = bool(trigger)
            if asynchronous:
                state["muon_warm_async_checks_completed"] = int(
                    state.get("muon_warm_async_checks_completed", 0)
                ) + 1

    def _drain_pending_drift_checks(self):
        pending_checks = getattr(
            self, "_muon_warm_pending_drift_checks", {}
        )
        reusable_buffers = getattr(
            self, "_muon_warm_drift_host_buffers", {}
        )
        for device, pending in tuple(pending_checks.items()):
            if not pending["event"].query():
                continue
            triggers = (
                pending["host_signals"] > float(pending["threshold"])
            ).tolist()
            self._apply_drift_check_results(
                pending["entries"],
                triggers,
                pending["flag_key"],
                pending["checks_key"],
                True,
            )
            reusable_buffers[device] = pending["host_signals"]
            del pending_checks[device]
        self._muon_warm_pending_drift_checks = pending_checks
        self._muon_warm_drift_host_buffers = reusable_buffers

    def _prepare_angular_anchor_flags(self):
        # Poll before gathering a new check. Event.query() never waits for CUDA;
        # a completed copy therefore turns into an anchor flag one or more
        # optimizer steps after it was submitted.
        self._drain_pending_drift_checks()
        if self.muon_warm_max_skew_ratio > 0.0:
            threshold = self.muon_warm_max_skew_ratio
            signal_key = "muon_warm_skew_ratio_signal_tensor"
            flag_key = "muon_warm_force_skew_ratio_anchor"
            checks_key = "muon_warm_skew_ratio_checks"
        elif self.muon_warm_max_angular_rms > 0.0:
            threshold = self.muon_warm_max_angular_rms
            signal_key = "muon_warm_angular_signal_tensor"
            flag_key = "muon_warm_force_angular_anchor"
            checks_key = "muon_warm_angular_checks"
        else:
            return
        by_device = {}
        for group in self.param_groups:
            if not group.get("use_muon", False):
                continue
            for parameter in group["params"]:
                parameter_state = self.state.get(parameter)
                if not parameter_state:
                    continue
                states = parameter_state.get("muon_block_states")
                if states is None:
                    states = (parameter_state,)
                for state in states:
                    next_step = int(state.get("step", 0)) + 1
                    if next_step % self.muon_warm_check_every != 0:
                        continue
                    signal = state.get(signal_key)
                    if signal is None:
                        continue
                    by_device.setdefault(signal.device, []).append((state, signal))
        for entries in by_device.values():
            device = entries[0][1].device
            pending_checks = self._muon_warm_pending_drift_checks
            if (
                self.muon_warm_async_checks
                and device.type == "cuda"
                and device in pending_checks
            ):
                for state, _ in entries:
                    state["muon_warm_async_enqueue_skips"] = int(
                        state.get("muon_warm_async_enqueue_skips", 0)
                    ) + 1
                continue
            signals = torch.stack([signal for _, signal in entries])
            result_entries = [
                (state, int(state.get("muon_warm_anchor_serial", 0)))
                for state, _ in entries
            ]
            if self.muon_warm_async_checks and signals.device.type == "cuda":
                reusable_buffers = getattr(
                    self, "_muon_warm_drift_host_buffers", {}
                )
                host_signals = reusable_buffers.pop(device, None)
                if (
                    host_signals is None
                    or host_signals.shape != signals.shape
                    or host_signals.dtype != signals.dtype
                ):
                    host_signals = torch.empty(
                        signals.shape,
                        dtype=signals.dtype,
                        device="cpu",
                        pin_memory=True,
                    )
                host_signals.copy_(signals, non_blocking=True)
                event = torch.cuda.Event()
                event.record(torch.cuda.current_stream(device))
                pending_checks[device] = {
                    "entries": result_entries,
                    "host_signals": host_signals,
                    "event": event,
                    "threshold": float(threshold),
                    "flag_key": flag_key,
                    "checks_key": checks_key,
                }
                self._muon_warm_drift_host_buffers = reusable_buffers
                for state, _ in entries:
                    state["muon_warm_async_checks_submitted"] = int(
                        state.get("muon_warm_async_checks_submitted", 0)
                    ) + 1
            else:
                triggers = (signals > float(threshold)).tolist()
                self._apply_drift_check_results(
                    result_entries,
                    triggers,
                    flag_key,
                    checks_key,
                    False,
                )

    def _compute_warm_direction(
        self,
        tracking_matrix,
        q_prev,
        alignment_matrix,
        state,
        transposed,
    ):
        state["muon_warm_did_output_retract"] = bool(
            self.muon_warm_legacy_retraction_output
        )
        warm_index = int(state.get("muon_warm_age", 0)) + 1
        retract_now = warm_index % self.muon_warm_retract_every == 0
        retract_steps = (
            int(self.muon_warm_retract_steps) if retract_now else 0
        )
        state["muon_warm_did_retract"] = bool(retract_steps > 0)
        arguments = (
            tracking_matrix,
            q_prev,
            float(self.muon_warm_lr),
            float(self.muon_warm_jacobi_eps),
            self.muon_warm_retract_method,
            retract_steps,
            self.muon_warm_track_subspace,
            alignment_matrix,
            self.muon_warm_jacobi_damping,
        )
        power_mode = self.muon_warm_spectral_cap_mode in (
            "power",
            "power_step",
        )
        power_step_mode = self.muon_warm_spectral_cap_mode == "power_step"
        power_vector = state.get("muon_warm_power_vector")
        dynamic_normal_inv_cap = self._normal_inv_dynamic_cap(state)
        if (
            self.muon_warm_max_tangent_rms <= 0.0
            and self.muon_warm_alignment_tolerance < 0.0
            and not self.muon_warm_record_stats
            and self.muon_warm_max_tangent_ratio <= 0.0
            and self.muon_warm_max_rejection_streak <= 0
        ):
            if power_mode:
                if power_step_mode:
                    if self.muon_warm_max_skew_ratio > 0.0:
                        skew_ratio_step = (
                            _warm_polar_jacobi_step_power_step_cap_with_skew_ratio_signal
                            if retract_steps > 0
                            else _warm_polar_jacobi_step_power_step_cap_with_skew_ratio_signal_no_cache_retract
                        )
                        (
                            q_next,
                            output_direction,
                            skew_ratio_signal,
                            power_vector,
                            power_sigma,
                            cap_scale,
                            probe_sigma,
                            step_scale,
                        ) = skew_ratio_step(
                            *arguments,
                            power_vector,
                            self.muon_warm_power_steps,
                            self.muon_warm_power_safety_factor,
                            self.muon_warm_legacy_retraction_output,
                            self.muon_warm_angular_scale,
                            self.muon_warm_normal_scale,
                            self.muon_warm_normal_inv_cap,
                        )
                        state["muon_warm_skew_ratio_signal_tensor"] = (
                            skew_ratio_signal
                        )
                        if self.muon_warm_legacy_retraction_output:
                            state["muon_warm_legacy_output_direction"] = (
                                output_direction
                            )
                    elif self.muon_warm_max_angular_rms > 0.0:
                        angular_step = (
                            _warm_polar_jacobi_step_power_step_cap_with_angular_signal
                            if retract_steps > 0
                            else _warm_polar_jacobi_step_power_step_cap_with_angular_signal_no_cache_retract
                        )
                        (
                            q_next,
                            output_direction,
                            angular_signal,
                            power_vector,
                            power_sigma,
                            cap_scale,
                            probe_sigma,
                            step_scale,
                        ) = angular_step(
                            *arguments,
                            power_vector,
                            self.muon_warm_power_steps,
                            self.muon_warm_power_safety_factor,
                            self.muon_warm_legacy_retraction_output,
                            self.muon_warm_angular_scale,
                            self.muon_warm_normal_scale,
                            self.muon_warm_normal_inv_cap,
                        )
                        state["muon_warm_angular_signal_tensor"] = (
                            angular_signal
                        )
                        if self.muon_warm_legacy_retraction_output:
                            state["muon_warm_legacy_output_direction"] = (
                                output_direction
                            )
                    elif self.muon_warm_legacy_retraction_output:
                        legacy_step = (
                            _warm_polar_jacobi_step_power_step_cap_with_legacy_output
                            if retract_steps > 0
                            else _warm_polar_jacobi_step_power_step_cap_with_legacy_output_no_cache_retract
                        )
                        (
                            q_next,
                            output_direction,
                            power_vector,
                            power_sigma,
                            cap_scale,
                            probe_sigma,
                            step_scale,
                        ) = legacy_step(
                            *arguments,
                            power_vector,
                            self.muon_warm_power_steps,
                            self.muon_warm_power_safety_factor,
                            self.muon_warm_angular_scale,
                            self.muon_warm_normal_scale,
                            self.muon_warm_normal_inv_cap,
                        )
                        state["muon_warm_legacy_output_direction"] = (
                            output_direction
                        )
                    else:
                        (
                            q_next,
                            power_vector,
                            power_sigma,
                            cap_scale,
                            probe_sigma,
                            step_scale,
                        ) = _warm_polar_jacobi_step_power_step_cap(
                            *arguments,
                            power_vector,
                            self.muon_warm_power_steps,
                            self.muon_warm_power_safety_factor,
                            self.muon_warm_angular_scale,
                            self.muon_warm_normal_scale,
                            self.muon_warm_normal_inv_cap,
                        )
                else:
                    q_next, power_vector, power_sigma, cap_scale = (
                        _warm_polar_jacobi_step_power_cap(
                            *arguments,
                            power_vector,
                            self.muon_warm_power_steps,
                            self.muon_warm_power_safety_factor,
                            self.muon_warm_angular_scale,
                            self.muon_warm_normal_scale,
                            self.muon_warm_normal_inv_cap,
                        )
                    )
                    probe_sigma = step_scale = None
                self._record_power_cap_state(
                    state,
                    power_vector,
                    power_sigma,
                    cap_scale,
                    probe_sigma,
                    step_scale,
                    retract_steps > 0,
                )
                return q_next
            if self.muon_warm_normal_inv_ema_ratio > 0.0:
                q_next, normal_inv_observation_rms = (
                    _warm_polar_jacobi_step_with_normal_inv_observation(
                        *arguments,
                        self.muon_warm_angular_scale,
                        self.muon_warm_normal_scale,
                        self.muon_warm_normal_inv_cap,
                        dynamic_normal_inv_cap,
                    )
                )
                if tracking_matrix.shape[-1] > tracking_matrix.shape[-2]:
                    self._record_normal_inv_ema_state(
                        state,
                        normal_inv_observation_rms,
                        dynamic_normal_inv_cap,
                    )
                return q_next
            if self.muon_warm_max_angular_rms > 0.0:
                q_next, angular_signal = (
                    _warm_polar_jacobi_step_with_angular_signal(
                        *arguments,
                        self.muon_warm_angular_scale,
                        self.muon_warm_normal_scale,
                        self.muon_warm_normal_inv_cap,
                    )
                )
                state["muon_warm_angular_signal_tensor"] = angular_signal
                return q_next
            return _warm_polar_jacobi_step(
                *arguments,
                angular_scale=self.muon_warm_angular_scale,
                normal_scale=self.muon_warm_normal_scale,
                normal_inv_cap=self.muon_warm_normal_inv_cap,
            )
        tangent_ema_sq = state.get("muon_warm_tangent_ema_sq_tensor")
        dynamic_tangent_cap = None
        if (
            self.muon_warm_max_tangent_ratio > 0.0
            and tangent_ema_sq is not None
        ):
            dynamic_tangent_cap = (
                float(self.muon_warm_max_tangent_ratio)
                * tangent_ema_sq.sqrt()
            )
        if power_mode:
            if power_step_mode:
                if self.muon_warm_legacy_retraction_output:
                    legacy_step_with_stats = (
                        _warm_polar_jacobi_step_power_step_cap_with_stats_and_legacy_output
                        if retract_steps > 0
                        else _warm_polar_jacobi_step_power_step_cap_with_stats_and_legacy_output_no_cache_retract
                    )
                    (
                        q_next,
                        output_direction,
                        stats,
                        power_vector,
                        power_sigma,
                        cap_scale,
                        probe_sigma,
                        step_scale,
                    ) = legacy_step_with_stats(
                        *arguments,
                        self.muon_warm_max_tangent_rms,
                        self.muon_warm_alignment_tolerance,
                        dynamic_tangent_cap,
                        power_vector,
                        self.muon_warm_power_steps,
                        self.muon_warm_power_safety_factor,
                        self.muon_warm_angular_scale,
                        self.muon_warm_normal_scale,
                        self.muon_warm_normal_inv_cap,
                    )
                    state["muon_warm_legacy_output_direction"] = (
                        output_direction
                    )
                else:
                    (
                        q_next,
                        stats,
                        power_vector,
                        power_sigma,
                        cap_scale,
                        probe_sigma,
                        step_scale,
                    ) = _warm_polar_jacobi_step_power_step_cap_with_stats(
                        *arguments,
                        self.muon_warm_max_tangent_rms,
                        self.muon_warm_alignment_tolerance,
                        dynamic_tangent_cap,
                        power_vector,
                        self.muon_warm_power_steps,
                        self.muon_warm_power_safety_factor,
                        self.muon_warm_angular_scale,
                        self.muon_warm_normal_scale,
                        self.muon_warm_normal_inv_cap,
                    )
            else:
                q_next, stats, power_vector, power_sigma, cap_scale = (
                    _warm_polar_jacobi_step_power_cap_with_stats(
                        *arguments,
                        self.muon_warm_max_tangent_rms,
                        self.muon_warm_alignment_tolerance,
                        dynamic_tangent_cap,
                        power_vector,
                        self.muon_warm_power_steps,
                        self.muon_warm_power_safety_factor,
                        self.muon_warm_angular_scale,
                        self.muon_warm_normal_scale,
                        self.muon_warm_normal_inv_cap,
                    )
                )
                probe_sigma = step_scale = None
            self._record_power_cap_state(
                state,
                power_vector,
                power_sigma,
                cap_scale,
                probe_sigma,
                step_scale,
                retract_steps > 0,
            )
        else:
            q_next, stats = _warm_polar_jacobi_step_with_stats(
                *arguments,
                self.muon_warm_max_tangent_rms,
                self.muon_warm_alignment_tolerance,
                dynamic_tangent_cap,
                self.muon_warm_angular_scale,
                self.muon_warm_normal_scale,
                self.muon_warm_normal_inv_cap,
                dynamic_normal_inv_cap,
            )
        state["muon_warm_effective_eta_tensor"] = stats[0]
        state["muon_warm_tangent_rms_tensor"] = stats[1]
        state["muon_warm_step_accepted_tensor"] = stats[2]
        state["muon_warm_angular_rms_tensor"] = stats[3]
        state["muon_warm_normal_rms_tensor"] = stats[4]
        state["muon_warm_relative_min_abs_diag_tensor"] = stats[5]
        state["muon_warm_relative_max_abs_inv_tensor"] = stats[6]
        state["muon_warm_normal_inv_clipped_fraction_tensor"] = stats[7]
        state["muon_warm_normal_inv_observation_rms_tensor"] = stats[8]
        state["muon_warm_skew_ratio_tensor"] = stats[9]
        if self.muon_warm_max_angular_rms > 0.0:
            state["muon_warm_angular_signal_tensor"] = stats[3]
        if self.muon_warm_max_skew_ratio > 0.0:
            state["muon_warm_skew_ratio_signal_tensor"] = stats[9]
        state["muon_warm_controller_samples"] = int(
            state.get("muon_warm_controller_samples", 0)
        ) + 1
        for name, value in (
            ("effective_eta", stats[0]),
            ("tangent_rms", stats[1]),
            ("angular_rms", stats[3]),
            ("normal_rms", stats[4]),
            ("skew_ratio", stats[9]),
        ):
            sum_key = f"muon_warm_{name}_sum_tensor"
            max_key = f"muon_warm_{name}_max_tensor"
            state[sum_key] = state.get(sum_key, torch.zeros_like(value)) + value
            state[max_key] = torch.maximum(state.get(max_key, value), value)
        if tracking_matrix.shape[-1] > tracking_matrix.shape[-2]:
            state["muon_warm_alignment_condition_samples"] = int(
                state.get("muon_warm_alignment_condition_samples", 0)
            ) + 1
            for name, value in (
                ("relative_min_abs_diag", stats[5]),
                ("relative_max_abs_inv", stats[6]),
                ("normal_inv_clipped_fraction", stats[7]),
                ("normal_inv_observation_rms", stats[8]),
            ):
                sum_key = f"muon_warm_{name}_sum_tensor"
                state[sum_key] = (
                    state.get(sum_key, torch.zeros_like(value)) + value
                )
            state["muon_warm_relative_min_abs_diag_min_tensor"] = torch.minimum(
                state.get(
                    "muon_warm_relative_min_abs_diag_min_tensor", stats[5]
                ),
                stats[5],
            )
            state["muon_warm_relative_max_abs_inv_max_tensor"] = torch.maximum(
                state.get(
                    "muon_warm_relative_max_abs_inv_max_tensor", stats[6]
                ),
                stats[6],
            )
            if self.muon_warm_normal_inv_ema_ratio > 0.0:
                self._record_normal_inv_ema_state(
                    state,
                    stats[8],
                    dynamic_normal_inv_cap,
                )
        applied_rms = stats[0] * stats[1]
        state["muon_warm_max_tangent_rms_tensor"] = torch.maximum(
            state.get("muon_warm_max_tangent_rms_tensor", stats[1]),
            stats[1],
        )
        state["muon_warm_max_applied_tangent_rms_tensor"] = torch.maximum(
            state.get("muon_warm_max_applied_tangent_rms_tensor", applied_rms),
            applied_rms,
        )
        state["muon_warm_min_effective_eta_tensor"] = torch.minimum(
            state.get("muon_warm_min_effective_eta_tensor", stats[0]),
            stats[0],
        )
        if self.muon_warm_max_tangent_ratio > 0.0:
            proposed_square = stats[1].square()
            if tangent_ema_sq is None:
                tangent_ema_sq = proposed_square
            else:
                tangent_ema_sq = tangent_ema_sq.lerp(
                    proposed_square,
                    1.0 - self.muon_warm_tangent_ema_beta,
                )
            state["muon_warm_tangent_ema_sq_tensor"] = tangent_ema_sq
            state["muon_warm_dynamic_cap_tensor"] = (
                dynamic_tangent_cap
                if dynamic_tangent_cap is not None
                else stats[1].new_tensor(-1.0)
            )
        return q_next

    def _muon_update_warm(self, grad, state, group):
        state.pop("muon_warm_legacy_output_direction", None)
        state["muon_warm_did_output_retract"] = False
        record_update = (
            self.muon_warm_update_stats_every > 0
            and state["step"] % self.muon_warm_update_stats_every == 0
        )
        momentum_innovation_ratio = None
        if record_update:
            momentum_delta_sq = (
                (grad.float() - state["momentum_fast"].float()).square().sum()
                * (1.0 - float(group["momentum"])) ** 2
            )
        state["momentum_fast"].lerp_(grad, 1 - group["momentum"])
        if record_update:
            momentum_innovation_ratio = (
                momentum_delta_sq
                / state["momentum_fast"].float().square().sum().clamp_min(1e-30)
            ).sqrt()
        update = (
            torch.lerp(grad, state["momentum_fast"], group["momentum"])
            if self.muon_nesterov
            else state["momentum_fast"]
        )
        original_shape = update.shape
        if update.ndim == 4:
            update = update.view(len(update), -1)
        matrix_shape = update.shape

        work_matrix, transposed = _prepare_muon_matrix(update)
        q_prev = state.get("muon_warm_q")
        anchor_offset = (
            state.get("muon_warm_anchor_offset", 0)
            if self.muon_warm_stagger_anchors
            else 0
        )
        anchor_reason = None
        force_angular_anchor = bool(
            state.pop("muon_warm_force_angular_anchor", False)
        )
        force_skew_ratio_anchor = bool(
            state.pop("muon_warm_force_skew_ratio_anchor", False)
        )
        if q_prev is None:
            anchor_reason = "initial"
        elif (
            q_prev.shape != work_matrix.shape
            or q_prev.device != work_matrix.device
            or q_prev.dtype != work_matrix.dtype
        ):
            anchor_reason = "state_reset"
        elif state["step"] <= self.muon_warm_full_ns_steps:
            anchor_reason = "warmup"
        elif (
            self.muon_warm_anchor_every > 0
            and (state["step"] + anchor_offset)
            % self.muon_warm_anchor_every
            == 0
        ):
            anchor_reason = "schedule"
        elif (
            self.muon_warm_max_age > 0
            and int(state.get("muon_warm_age", 0)) >= self.muon_warm_max_age
        ):
            anchor_reason = "max_age"
        elif force_angular_anchor:
            anchor_reason = "angular_rms"
        elif force_skew_ratio_anchor:
            anchor_reason = "skew_ratio"
        needs_anchor = anchor_reason is not None
        tracking_matrix = (
            work_matrix
            if needs_anchor
            else self._prepare_tracking_matrix(
                work_matrix,
                q_prev,
                state,
                transposed,
            )
        )
        alignment_matrix = None
        check_tracking = (
            not needs_anchor
            and (
                self.muon_warm_max_tracking_error > 0.0
                or self.muon_warm_min_alignment > 0.0
                or self.muon_warm_min_stretch > 0.0
                or self.muon_warm_max_rejection_streak > 0
            )
            and state["step"] % self.muon_warm_check_every == 0
        )
        if check_tracking:
            alignment_matrix, metrics = _warm_alignment_metrics(
                tracking_matrix, q_prev
            )
            rejection_streak_tensor = state.get(
                "muon_warm_rejection_streak_tensor",
                metrics.new_tensor(0.0),
            )
            combined_metrics = torch.cat(
                (metrics, rejection_streak_tensor.reshape(1))
            )
            (
                rotation_error,
                subspace_error,
                relative_alignment,
                relative_min_stretch,
                rejection_streak,
            ) = combined_metrics.tolist()
            state["muon_warm_rotation_error"] = rotation_error
            state["muon_warm_subspace_error"] = subspace_error
            state["muon_warm_relative_alignment"] = relative_alignment
            state["muon_warm_relative_min_stretch"] = relative_min_stretch
            state["muon_warm_rejection_streak"] = rejection_streak
            if (
                self.muon_warm_max_rejection_streak > 0
                and rejection_streak >= self.muon_warm_max_rejection_streak
            ):
                anchor_reason = "rejection_streak"
            elif (
                self.muon_warm_max_tracking_error > 0.0
                and max(rotation_error, subspace_error)
                > self.muon_warm_max_tracking_error
            ):
                anchor_reason = "tracking_error"
            elif (
                self.muon_warm_min_alignment > 0.0
                and relative_alignment < self.muon_warm_min_alignment
            ):
                anchor_reason = "alignment"
            elif (
                self.muon_warm_min_stretch > 0.0
                and relative_min_stretch < self.muon_warm_min_stretch
            ):
                anchor_reason = "stretch"
            needs_anchor = anchor_reason is not None
        if needs_anchor:
            state["muon_warm_anchor_serial"] = int(
                state.get("muon_warm_anchor_serial", 0)
            ) + 1
            q_next = self._compute_anchor_direction(
                work_matrix,
                state,
                transposed,
            )
            state["muon_warm_did_retract"] = bool(
                self.muon_warm_anchor_retract_steps > 0
            )
            state["muon_warm_rejection_streak_tensor"] = q_next.new_tensor(
                0.0, dtype=torch.float32
            )
            state.pop("muon_warm_power_vector", None)
            state.pop("muon_warm_angular_signal_tensor", None)
            state.pop("muon_warm_skew_ratio_signal_tensor", None)
        else:
            q_next = self._compute_warm_direction(
                tracking_matrix,
                q_prev,
                alignment_matrix,
                state,
                transposed,
            )
            if self.muon_warm_max_rejection_streak > 0:
                accepted = state["muon_warm_step_accepted_tensor"]
                previous_streak = state.get(
                    "muon_warm_rejection_streak_tensor",
                    accepted.new_tensor(0.0),
                )
                state["muon_warm_rejection_streak_tensor"] = torch.where(
                    accepted > 0.5,
                    torch.zeros_like(previous_streak),
                    previous_streak + 1.0,
                )
        state["muon_warm_did_anchor"] = bool(needs_anchor)
        state["muon_warm_anchor_reason"] = anchor_reason or "warm"
        if needs_anchor:
            anchor_counts = state.setdefault("muon_warm_anchor_counts", {})
            anchor_counts[anchor_reason] = anchor_counts.get(anchor_reason, 0) + 1
        else:
            state["muon_warm_warm_steps"] = int(
                state.get("muon_warm_warm_steps", 0)
            ) + 1
            if state.get("muon_warm_did_retract", False):
                state["muon_warm_warm_retractions"] = int(
                    state.get("muon_warm_warm_retractions", 0)
                ) + 1
            if state.get("muon_warm_did_output_retract", False):
                state["muon_warm_output_retractions"] = int(
                    state.get("muon_warm_output_retractions", 0)
                ) + 1
            if self.muon_warm_alignment_tolerance >= 0.0:
                rejected = 1.0 - state["muon_warm_step_accepted_tensor"]
                previous_rejections = state.get(
                    "muon_warm_rejections_tensor",
                    rejected.new_tensor(0.0),
                )
                state["muon_warm_rejections_tensor"] = (
                    previous_rejections + rejected
                )
        state["muon_warm_age"] = (
            0 if needs_anchor else int(state.get("muon_warm_age", 0)) + 1
        )
        state["muon_warm_q"] = q_next.contiguous()
        output_direction = state.pop(
            "muon_warm_legacy_output_direction",
            q_next,
        )
        warm_output_scale = 1.0
        if not needs_anchor:
            warm_output_scale = self.muon_warm_output_scale
            if self.muon_warm_output_scale_start is not None:
                warm_output_scale = self.muon_warm_output_scale + (
                    self.muon_warm_output_scale_start
                    - self.muon_warm_output_scale
                ) * math.exp(
                    -self.muon_warm_output_scale_decay
                    * max(0, int(state["muon_warm_age"]) - 1)
                )

        if record_update:
            # Accumulate scalar tensors on device and transfer them only when
            # diagnostics are requested after training.  The reference solve is
            # deliberately opt-in because it performs the full anchor work.
            q_float = output_direction.float()
            matrix_float = work_matrix.float()
            aspect_scale = max(
                1.0,
                float(matrix_shape[-2]) / float(matrix_shape[-1]),
            ) ** 0.5
            measurement_scale = aspect_scale
            if self.muon_warm_normalize_output:
                target_norm = math.sqrt(max(1, matrix_shape[-2]))
                measurement_scale = float(target_norm) / (
                    q_float.norm().clamp_min(1e-12)
                )
            measurement_scale = measurement_scale * warm_output_scale
            direction_sq = q_float.square().sum() * measurement_scale**2
            momentum_sq = matrix_float.square().sum()
            direction_momentum_dot = (
                q_float * matrix_float
            ).sum() * measurement_scale
            gram = q_float @ q_float.mT
            identity = torch.eye(
                gram.shape[-1], device=gram.device, dtype=gram.dtype
            )
            orthogonality_error = (
                (gram - identity).norm()
                / math.sqrt(max(1, gram.shape[-1]))
            )
            learning_rate = float(group["lr"])

            def accumulate(key, value):
                state[key] = state.get(key, torch.zeros_like(value)) + value

            accumulate("muon_update_direction_sq_sum_tensor", direction_sq)
            accumulate("muon_update_momentum_sq_sum_tensor", momentum_sq)
            accumulate(
                "muon_update_direction_momentum_dot_sum_tensor",
                direction_momentum_dot,
            )
            accumulate(
                "muon_update_applied_sq_sum_tensor",
                direction_sq * learning_rate**2,
            )
            accumulate(
                "muon_update_orthogonality_error_sum_tensor",
                orthogonality_error,
            )
            state["muon_update_max_orthogonality_error_tensor"] = torch.maximum(
                state.get(
                    "muon_update_max_orthogonality_error_tensor",
                    orthogonality_error,
                ),
                orthogonality_error,
            )
            state["muon_update_elements"] = int(
                state.get("muon_update_elements", 0)
            ) + q_next.numel()
            state["muon_update_samples"] = int(
                state.get("muon_update_samples", 0)
            ) + 1

            age = int(state["muon_warm_age"])
            age_statistics = state.setdefault("muon_update_stats_by_age", {})
            age_bucket = age_statistics.setdefault(age, {})

            def accumulate_age(key, value):
                age_bucket[key] = age_bucket.get(
                    key, torch.zeros_like(value)
                ) + value

            for key, value in (
                ("direction_sq_sum_tensor", direction_sq),
                ("momentum_sq_sum_tensor", momentum_sq),
                ("direction_momentum_dot_sum_tensor", direction_momentum_dot),
                ("applied_sq_sum_tensor", direction_sq * learning_rate**2),
                ("orthogonality_error_sum_tensor", orthogonality_error),
            ):
                accumulate_age(key, value)
            age_bucket["max_orthogonality_error_tensor"] = torch.maximum(
                age_bucket.get(
                    "max_orthogonality_error_tensor", orthogonality_error
                ),
                orthogonality_error,
            )
            age_bucket["elements"] = int(age_bucket.get("elements", 0)) + q_next.numel()
            age_bucket["samples"] = int(age_bucket.get("samples", 0)) + 1

            if not needs_anchor:
                reference = self._compute_anchor_direction(
                    work_matrix,
                    state,
                    transposed,
                ).float()
                reference_sq = reference.square().sum() * aspect_scale**2
                reference_dot = (
                    q_float * reference
                ).sum() * measurement_scale * aspect_scale
                difference_sq = (
                    (
                        q_float * measurement_scale
                        - reference * aspect_scale
                    ).square().sum()
                )
                relative_reference_error = (
                    difference_sq / reference_sq.clamp_min(1e-30)
                ).sqrt()
                reference_lr = (
                    learning_rate * self.muon_warm_reference_lr_ratio
                )
                accumulate("muon_reference_direction_sq_sum_tensor", reference_sq)
                accumulate("muon_reference_direction_dot_sum_tensor", reference_dot)
                accumulate("muon_reference_difference_sq_sum_tensor", difference_sq)
                accumulate(
                    "muon_reference_candidate_applied_sq_sum_tensor",
                    direction_sq * learning_rate**2,
                )
                accumulate(
                    "muon_reference_applied_sq_sum_tensor",
                    reference_sq * reference_lr**2,
                )
                state["muon_reference_elements"] = int(
                    state.get("muon_reference_elements", 0)
                ) + reference.numel()
                state["muon_reference_samples"] = int(
                    state.get("muon_reference_samples", 0)
                ) + 1
                for key, value in (
                    ("reference_direction_sq_sum_tensor", reference_sq),
                    ("reference_direction_dot_sum_tensor", reference_dot),
                    ("reference_difference_sq_sum_tensor", difference_sq),
                    (
                        "candidate_applied_sq_sum_tensor",
                        direction_sq * learning_rate**2,
                    ),
                    (
                        "reference_applied_sq_sum_tensor",
                        reference_sq * reference_lr**2,
                    ),
                ):
                    accumulate_age(key, value)
                age_bucket["reference_elements"] = int(
                    age_bucket.get("reference_elements", 0)
                ) + reference.numel()
                age_bucket["reference_samples"] = int(
                    age_bucket.get("reference_samples", 0)
                ) + 1
                predictor_values = {
                    "momentum_innovation_ratio": momentum_innovation_ratio,
                }
                if "muon_warm_tangent_rms_tensor" in state:
                    predictor_values.update(
                        {
                            "tangent_rms": state[
                                "muon_warm_tangent_rms_tensor"
                            ],
                            "angular_rms": state[
                                "muon_warm_angular_rms_tensor"
                            ],
                            "normal_rms": state[
                                "muon_warm_normal_rms_tensor"
                            ],
                        }
                    )
                    if tracking_matrix.shape[-1] > tracking_matrix.shape[-2]:
                        predictor_values.update(
                            {
                                "relative_max_abs_inverse": state[
                                    "muon_warm_relative_max_abs_inv_tensor"
                                ],
                                "normal_inverse_clipped_fraction": state[
                                    "muon_warm_normal_inv_clipped_fraction_tensor"
                                ],
                            }
                        )
                for name, predictor in predictor_values.items():
                    if predictor is None:
                        continue
                    predictor = predictor.float()
                    for suffix, value in (
                        ("sample", torch.ones_like(predictor)),
                        ("value", predictor),
                        ("value_sq", predictor.square()),
                        ("error", relative_reference_error),
                        ("error_sq", relative_reference_error.square()),
                        (
                            "value_error",
                            predictor * relative_reference_error,
                        ),
                    ):
                        accumulate_age(
                            f"refresh_predictor_{name}_{suffix}_sum_tensor",
                            value,
                        )

        update = _restore_muon_matrix(output_direction, transposed)
        # Keep aspect-ratio scaling out of place.  `_restore_muon_matrix` may
        # return the same storage as the cached q_next, depending on layout.
        update = update * max(1, update.size(-2) / update.size(-1)) ** 0.5
        if self.muon_warm_normalize_output:
            # A row-orthogonal Muon direction has Frobenius norm sqrt(number of
            # output rows) after the aspect-ratio correction above.  Restore
            # only that scalar magnitude here; leave the cached basis untouched
            # so this cannot amplify its singular values or change transport.
            target_norm = math.sqrt(max(1, matrix_shape[-2]))
            output_scale = target_norm / update.float().norm().clamp_min(1e-12)
            update = update * output_scale.to(update.dtype)
        if warm_output_scale != 1.0:
            # Filter only the direction returned to the parameter update.  The
            # cached q_next above remains an unscaled transport iterate, so the
            # next warm step starts from the same geometry as the control.
            update = update * warm_output_scale
        return update.reshape(original_shape) if update.shape != original_shape else update

    @torch.no_grad()
    def step(self, closure=None):

        loss = None
        if closure is not None:
            with torch.enable_grad():
                loss = closure()

        self._prepare_angular_anchor_flags()

        for group in self.param_groups:
            if group["use_muon"]:
                for p in group["params"]:
                    if p.grad is None:
                        p.grad = torch.zeros_like(p)  # Force synchronization
                    state = self.state[p]
                    split_count = int(group.get("muon_split_count", 1))
                    if split_count > 1:
                        if p.ndim != 2 or p.shape[0] % split_count:
                            raise ValueError(
                                f"Muon row split {split_count} is incompatible "
                                f"with parameter shape {tuple(p.shape)}"
                            )
                        if len(state) == 0:
                            state["muon_block_states"] = [
                                {} for _ in range(split_count)
                            ]
                        block_states = state.get("muon_block_states")
                        if block_states is None or len(block_states) != split_count:
                            raise ValueError(
                                "Loaded Muon block state does not match the "
                                "configured row split"
                            )
                        updates = []
                        for grad_block, block_state in zip(
                            p.grad.chunk(split_count, dim=0), block_states
                        ):
                            if len(block_state) == 0:
                                block_state["momentum_fast"] = torch.zeros_like(
                                    grad_block
                                )
                                block_state["step"] = 0
                                if self.muon_warm_anchor_every > 0:
                                    block_state["muon_warm_anchor_offset"] = (
                                        self._next_muon_anchor_offset
                                        % self.muon_warm_anchor_every
                                    )
                                    self._next_muon_anchor_offset += 1
                            block_state["step"] += 1
                            updates.append(
                                self._muon_update_warm(
                                    grad_block,
                                    block_state,
                                    group,
                                )
                            )
                        update = torch.cat(updates, dim=0)
                    else:
                        if len(state) == 0:
                            state["momentum_fast"] = torch.zeros_like(p)
                            state["step"] = 0
                            if self.muon_warm_anchor_every > 0:
                                state["muon_warm_anchor_offset"] = (
                                    self._next_muon_anchor_offset
                                    % self.muon_warm_anchor_every
                                )
                                self._next_muon_anchor_offset += 1
                        state["step"] += 1
                        update = self._muon_update_warm(p.grad, state, group)
                    
                    p.mul_(1 - group["lr"] * group["weight_decay"])
                    p.add_(update.reshape(p.shape), alpha=-group["lr"])
            else:
                for p in group["params"]:
                    if p.grad is None:
                        p.grad = torch.zeros_like(p)  # Force synchronization
                    state = self.state[p]
                    if len(state) == 0:
                        state["exp_avg"] = torch.zeros_like(p)
                        state["exp_avg_sq"] = torch.zeros_like(p)
                        state["step"] = 0
                    state["step"] += 1
                    update = adam_update(p.grad, state["exp_avg"], state["exp_avg_sq"],
                                         state["step"], group["betas"], group["eps"])
                    p.mul_(1 - group["lr"] * group["weight_decay"])
                    p.add_(update, alpha=-group["lr"])

        return loss
